"""Copy every settlement from the Clearwell Settlements API into settlements.jsonl."""
import argparse
import json
import time
import urllib.error
import urllib.request

QUERY = """query Settlements($after: String) {
  settlements(first: 100, after: $after) {
    nodes { id batchDate amountCents currency status }
    pageInfo { endCursor hasNextPage }
  }
}"""


def graphql(url, query, variables=None):
    body = json.dumps({"query": query, "variables": variables or {}}).encode()
    while True:
        req = urllib.request.Request(
            url, data=body, headers={"Content-Type": "application/json"}
        )
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                result = json.load(resp)
            break
        except urllib.error.HTTPError as exc:
            if exc.code != 429:
                raise
            retry_after = exc.headers.get("Retry-After", "1")
            try:
                delay = float(retry_after)
            except ValueError:
                delay = 1.0
            time.sleep(delay)
    if result.get("errors"):
        raise RuntimeError(result["errors"])
    return result["data"]


def fetch_settlements(url):
    # Amended settlements are delivered again later in the traversal; the last
    # version seen for an id wins, so key by id.
    settlements = {}
    after = None
    restarted = False
    while True:
        try:
            data = graphql(url, QUERY, {"after": after})
        except RuntimeError:
            # A malformed or expired cursor is a GraphQL error: start over
            # without `after`. Deduplication makes the replay harmless.
            if after is not None and not restarted:
                after = None
                restarted = True
                continue
            raise
        connection = data["settlements"]
        for settlement in connection["nodes"]:
            settlements[settlement["id"]] = settlement
        page_info = connection["pageInfo"]
        if not page_info["hasNextPage"]:
            break
        after = page_info["endCursor"]
    return list(settlements.values())


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-url", required=True)
    ap.add_argument("--out", default="settlements.jsonl")
    args = ap.parse_args()
    settlements = fetch_settlements(f"{args.base_url.rstrip('/')}/v2/graphql")
    with open(args.out, "w") as f:
        for s in settlements:
            f.write(json.dumps(s) + "\n")
    print(f"reconciled {len(settlements)} settlements")


if __name__ == "__main__":
    main()

